insert into fx select 'pet',id from save_patient(null,(select id from fx where k='client'),null,'Scoped dog','Dog',null,null,'unknown',null,'unknown','unknown',null,null,null);
insert into fx select k,gen_random_uuid() from unnest(array['mapping','mapping2','snapshot','snapshot2','legacy','terminal','run','history','other-run']) k;
reset role;
insert into ezyvet_import_snapshots(id,source_origin,source_site_uid,resource,external_id,payload,payload_hash,first_seen_by) select id,'https://api.trial.ezyvet.com','vaccination-test-site','animal',case when k='snapshot' then '77' else '88' end,jsonb_build_object('id',case when k='snapshot' then 77 else 88 end),k,'db520000-0000-4000-8000-000000000001' from fx where k in ('snapshot','snapshot2');
insert into ezyvet_record_links(id,request_id,request_hash,source_origin,source_site_uid,resource,external_id,snapshot_id,head_version,client_id,pet_id,local_version,action,reason,approved_by)
select id,gen_random_uuid(),k,'https://api.trial.ezyvet.com','vaccination-test-site','animal',case when k='mapping' then '77' else '88' end,(select id from fx where k=case when m.k='mapping' then 'snapshot' else 'snapshot2' end),1,(select id from fx where k='client'),(select id from fx where k='pet'),1,'link','Synthetic approved mapping','db520000-0000-4000-8000-000000000001' from fx m where k in ('mapping','mapping2');
insert into fx values('consult-run',gen_random_uuid());
insert into data select 'consult-run',claim_ezyvet_clinical_import((select id from fx where k='consult-run'),'db520000-0000-4000-8000-000000000001','vaccination-test-site','consult','https://api.trial.ezyvet.com',(select id from fx where k='mapping'));
select stage_ezyvet_import_page((select id from fx where k='consult-run'),'db520000-0000-4000-8000-000000000001',(select (v->>'lease_id')::uuid from data where k='consult-run'),1,true,'[{"external_id":"101","payload":{"id":101,"animal_id":77,"description":"Source consultation"}},{"external_id":"102","payload":{"id":102,"animal_id":77}}]');
insert into data select 'consult',list_ezyvet_clinical_candidates((select id from fx where k='mapping'),'consult')->'candidates'->0;
-- Choose external consult 101 independent of creation-order ties.
update data set v=(select c from jsonb_array_elements(list_ezyvet_clinical_candidates((select id from fx where k='mapping'),'consult')->'candidates') c where c->>'external_id'='101') where k='consult';
insert into data values('items','[{"external_id":"501","payload":{"id":501,"consult_id":101,"product_id":null,"date_of_administration":null,"date_of_next_administration":"unknown","qty":"outside units","vet_id":"outside author","notes":"<script>outside prose</script>"}}]');
