select throws_ok($$select claim_ezyvet_import(gen_random_uuid(),'db520000-0000-4000-8000-000000000001','vaccination-test-site','vaccination','https://api.trial.ezyvet.com')$$,'23514',null,'Generic vaccination blocked');
select throws_ok($$select claim_ezyvet_vaccination_import((select id from fx where k='legacy'),'db520000-0000-4000-8000-000000000001','vaccination-test-site','vaccination','https://api.trial.ezyvet.com',(select id from fx where k='mapping'),(select (v->>'id')::uuid from data where k='consult'),(select v->>'payload_hash' from data where k='consult'),(select (v->>'observed_head_version')::integer from data where k='consult'))$$,'22023',null,'legacy UUID cannot rebind');
