select throws_ok($$select claim_ezyvet_vaccination_import((select id from fx where k='run'),'db520000-0000-4000-8000-000000000001','vaccination-test-site','vaccination','https://api.trial.ezyvet.com',(select id from fx where k='mapping2'),(select (v->>'id')::uuid from data where k='consult'),(select v->>'payload_hash' from data where k='consult'),(select (v->>'observed_head_version')::integer from data where k='consult'))$$,'42501',null,'Foreign patient consult rejected');
select throws_ok($$select claim_ezyvet_vaccination_import((select id from fx where k='run'),'db520000-0000-4000-8000-000000000001','vaccination-test-site','vaccination','https://api.trial.ezyvet.com',(select id from fx where k='mapping'),(select (v->>'id')::uuid from data where k='consult'),(select v->>'payload_hash' from data where k='consult'),99)$$,'40001',null,'Wrong consult observed revision rejected');
reset role;
insert into data values('side-effects',jsonb_build_object('treatments',(select count(*) from patient_treatments),'invoices',(select count(*) from billing_invoices),'stock',(select count(*) from inventory_movements),'certificates',(select count(*) from vaccine_certificates),'reminders',(select count(*) from care_reminder_jobs),'outbox',(select count(*) from communication_outbox)));
