select is((select v->>'consult_external_id' from data where k='run'),'101','Claim derives consult ID from scoped source');
select throws_ok($$select claim_ezyvet_vaccination_import((select id from fx where k='run'),'db520000-0000-4000-8000-000000000002','vaccination-test-site','vaccination','https://api.trial.ezyvet.com',(select id from fx where k='mapping'),(select (v->>'id')::uuid from data where k='consult'),(select v->>'payload_hash' from data where k='consult'),(select (v->>'observed_head_version')::integer from data where k='consult'))$$,'42501',null,'Original actor immutable');
select throws_ok($$select claim_ezyvet_vaccination_import((select id from fx where k='run'),'db520000-0000-4000-8000-000000000001','vaccination-test-site','vaccination','https://api.trial.ezyvet.com',(select id from fx where k='mapping'),(select (v->>'id')::uuid from data where k='consult'),(select v->>'payload_hash' from data where k='consult'),2)$$,'42501',null,'Original consult revision immutable');
