select throws_ok($$select stage_ezyvet_import_page((select id from fx where k='run'),'db520000-0000-4000-8000-000000000001',(select (v->>'lease_id')::uuid from data where k='run'),1,false,'[{"external_id":"501","payload":{"id":501,"consult_id":"0101"}}]')$$,'23514',null,'Noncanonical or unsafe reference rejected');
select throws_ok($$select stage_ezyvet_import_page((select id from fx where k='run'),'db520000-0000-4000-8000-000000000001',(select (v->>'lease_id')::uuid from data where k='run'),1,false,'[{"external_id":"501","payload":{"id":501,"consult_id":101,"product_id":"9007199254740992"}}]')$$,'23514',null,'Noncanonical or unsafe reference rejected');
select throws_ok($$select stage_ezyvet_import_page((select id from fx where k='run'),'db520000-0000-4000-8000-000000000001',(select (v->>'lease_id')::uuid from data where k='run'),1,false,'[{"external_id":"501","payload":{"id":501,"consult_id":101,"product_id":true}}]')$$,'23514',null,'Noncanonical or unsafe reference rejected');
reset role;update ezyvet_import_runs set lease_until=now()-interval '1 second' where id=(select id from fx where k='run');set local role service_role;
select throws_ok($$select stage_ezyvet_import_page((select id from fx where k='run'),'db520000-0000-4000-8000-000000000001',(select (v->>'lease_id')::uuid from data where k='run'),1,false,(select v from data where k='items'))$$,'40001',null,'Expired lease rejected');
reset role;update ezyvet_import_runs set lease_until=now()+interval '90 seconds' where id=(select id from fx where k='run');set local role service_role;
select throws_ok($$select stage_ezyvet_import_page((select id from fx where k='run'),'db520000-0000-4000-8000-000000000001',(select (v->>'lease_id')::uuid from data where k='run'),1,false,'[{"external_id":"501","payload":{"id":501,"consult_id":101,"qty":[]}}]')$$,'23514',null,'Malformed optional qty rejected in SQL');
